window.SCIENCE_CURRICULUM = [{"id":"labstart","index":1,"name":"The Investigation Lab","subtitle":"Learning to think like a scientist","emoji":"🔬","theme":"Deep lab blue, glowing beakers, notebook sketches","palette":{"from":"#38bdf8","to":"#0ea5e9","accent":"#075985"},"lessons":[{"id":"is1","title":"A Scientist's Questions","icon":"🔍","kind":"lesson","story":"Grade 8 begins with a new mission: don't just learn facts — learn HOW to find them. Every great discovery starts with a question.","teach":[{"title":"From Wonder to Investigation","body":"In Grade 6 you learned science begins with wonder. In Grade 7, you learned science keeps evolving as each answer opens new questions. Now in Grade 8 you learn to investigate: ask focused questions, design simple experiments, and use observations to build understanding.","visual":"❓ → 🔬 → 💡"},{"title":"Probe and Ponder","body":"Not every question needs a lab. Why is one side of a puri thinner than the other? Are there more grains of sand on Earth's beaches or stars in our galaxy? These 'Probe and Ponder' questions aren't for exams — they're invitations to stay curious.","visual":"🫛 🏖️ ✨"}],"questions":[{"kind":"mcq","prompt":"What is the main new skill Grade 8's science book wants you to learn?","options":["How to memorise more facts","How to find new facts through investigation","How to pass exams faster","How to use a calculator"],"answer":1,"explain":"The chapter's whole point is learning HOW to investigate, not just memorising answers."},{"kind":"mcq","prompt":"According to the chapter, what did you learn in Grade 7 about science?","options":["Science never changes","Science is always evolving as each answer opens new questions","Science only happens in laboratories","Science has no unanswered questions"],"answer":1,"explain":"Grade 7 taught that each answer in science opens new questions."},{"kind":"fill","prompt":"Probe and ponder questions are meant to spark your ______, not test you for exams.","answer":"curiosity","placeholder":"one word","explain":"These questions exist purely to spark curiosity."}]},{"id":"is2","title":"The Puri Experiment","icon":"🫓","kind":"lesson","story":"Why does a puri puff up like a balloon when fried — and why is one side thinner? Let's investigate like a real scientist, right from the kitchen.","teach":[{"title":"What can we control?","body":"To investigate the puri, scientists change ONE variable at a time: dough thickness, type of flour, oil temperature, or how the dough is dropped into the oil — while keeping everything else the same.","visual":"🌾 🌡️ 📐"},{"title":"What can we observe?","body":"Some observations are yes/no (did it puff up?), others are measurements (how many seconds did it take?). Scientists record everything they notice — even the smell or splatter of the oil.","visual":"⏱️ 👀 📝"}],"questions":[{"kind":"mcq","prompt":"When testing how oil temperature affects a puri, what should you do with the dough thickness across trials?","options":["Change it randomly each time","Keep it the same so only temperature varies","Make it different every single time","It doesn't matter"],"answer":1,"explain":"Change only one variable at a time — this is the core idea of a controlled experiment."},{"kind":"match","prompt":"Match each item to what it is in the puri experiment.","pairs":[["Dough thickness","Something we control"],["Time to puff up","Something we measure"],["Oil temperature","Something we control"],["Whether it puffed up","A yes/no observation"]],"explain":"Controlled variables are what we change on purpose; observations are what we measure or note."},{"kind":"mcq","prompt":"Why is it good practice to keep notes of everything you see and sense during an experiment (smell, smoke, splatter)?","options":["It's required for a certificate","Unexpected details can reveal important clues","It makes the notebook look longer","It's not actually useful"],"answer":1,"explain":"Careful, complete notes often reveal clues a scientist would otherwise miss."}]},{"id":"is-boss","title":"The Curiosity Trials","icon":"🧠","kind":"boss","story":"This year's journey goes from invisible microbes to forces, matter, light, the sky, ecosystems, and finally planet Earth itself — all explored through the same investigative spirit.","teach":[{"title":"A Year of Investigation Ahead","body":"This year's investigative adventure travels from the tiny microbes we can't see to planet-wide challenges we can't ignore — covering health, electricity, forces, pressure, matter, light, the sky, ecosystems, and Earth itself.","visual":"🦠 ⚡ 🔭 🌍"}],"questions":[{"kind":"mcq","prompt":"In a controlled experiment, why do scientists change only one variable at a time?","options":["So the experiment finishes faster","So they can tell which variable actually caused the result","Because changing more than one is impossible","It doesn't actually matter"],"answer":1,"explain":"If you change only one variable, any difference in outcome can be traced to that one change."},{"kind":"mcq","prompt":"Even today, is the science behind why a puri puffs up completely understood by scientists?","options":["Yes, completely","No — even everyday things like this are still not fully understood","Only in India","Only for baturas"],"answer":1,"explain":"The chapter notes that even this everyday phenomenon isn't fully understood by scientists today!"},{"kind":"tap","prompt":"Tap the option that is NOT part of doing a systematic scientific investigation.","options":["Asking a focused question","Designing a simple experiment","Guessing without observing anything","Recording careful observations"],"answer":2,"explain":"Systematic investigation always involves careful observation — never guessing blindly."},{"kind":"fill","prompt":"Investigation in science means asking focused questions, designing experiments, and using ______ to improve understanding.","answer":"observations","placeholder":"one word","explain":"Careful observations are what let us turn experiments into understanding."},{"kind":"sort","prompt":"Sort this into the correct bin.","item":"Recording careful observations","bins":["Part of a systematic investigation","Not part of a systematic investigation"],"answer":0,"explain":"Investigation means asking focused questions, designing experiments, and recording observations — guessing without observing is not part of it."}],"boss":{"name":"The Skeptical Examiner","taunt":"Prove your questions are truly scientific — or I'll dismiss them as mere guesses!"}}]},{"id":"microcosm","index":2,"name":"The Microscopic Realm","subtitle":"Cells, microbes, and the invisible living world","emoji":"🦠","theme":"Glowing green petri-dish glow, cell walls, microscope light","palette":{"from":"#4ade80","to":"#16a34a","accent":"#14532d"},"lessons":[{"id":"mc1","title":"Cells: Life's Building Blocks","icon":"🧫","kind":"lesson","story":"In 1665, Robert Hooke looked through a microscope at a slice of cork and saw tiny empty spaces — he called them 'cells'. Let's explore what's really inside.","teach":[{"title":"Hooke & Leeuwenhoek","body":"Robert Hooke published Micrographia in 1665, drawing what his microscope showed him — including cork 'cells'. Around the same time, Antonie van Leeuwenhoek built powerful lenses and became the first to see bacteria and blood cells, earning him the title 'Father of Microbiology'.","visual":"🔬📖🦠"},{"title":"Three Basic Parts","body":"Every cell has a cell membrane (the porous outer boundary), cytoplasm (where most life processes happen), and a nucleus (which regulates the cell's activities and growth). Plant cells also have a rigid cell wall outside the membrane.","visual":"🧱🟢⚪"}],"questions":[{"kind":"mcq","prompt":"Who first used the word 'cell' after observing cork under a microscope in 1665?","options":["Antonie van Leeuwenhoek","Robert Hooke","Charles Darwin","Louis Pasteur"],"answer":1,"explain":"Robert Hooke coined the term 'cell' in his 1665 book Micrographia."},{"kind":"match","prompt":"Match each cell part to its job.","pairs":[["Cell membrane","Controls what enters and exits the cell"],["Nucleus","Regulates the cell's activities and growth"],["Cytoplasm","Where most life processes take place"],["Cell wall","Extra rigid layer found in plant cells"]],"explain":"Each part of the cell plays a distinct role in keeping it alive and functioning."},{"kind":"mcq","prompt":"Which part is found in plant cells but NOT in animal cells?","options":["Nucleus","Cytoplasm","Cell wall","Cell membrane"],"answer":2,"explain":"The rigid cell wall is an extra layer found only in plant (and fungal/bacterial) cells."},{"kind":"sort","prompt":"Sort this cell part into the correct bin.","item":"Cell wall","bins":["Found in plant cells","Found in animal cells"],"answer":0,"explain":"The cell wall is present in plant cells but not in animal cells."}]},{"id":"mc-lab","title":"The Microscope Lab","icon":"🔬","kind":"lesson","story":"Time to see it for yourself. Slide a real specimen under the microscope, turn the focus knob until it's sharp, and tap each structure to identify it.","teach":[{"title":"The Microscope Lab","kind":"microscope","body":"Drag the focus knob until the image is sharp, then tap each glowing structure to identify it.","specimens":[{"id":"onion","name":"Onion Cell (Plant)","shape":"rect","hotspots":[{"id":"wall","label":"Cell wall","x":12,"y":14,"fact":"A rigid outer layer that gives the cell its fixed shape — found in plant cells but not animal cells."},{"id":"membrane","label":"Cell membrane","x":22,"y":26,"fact":"The porous outer boundary that controls what enters and exits the cell."},{"id":"nucleus","label":"Nucleus","x":50,"y":52,"fact":"Regulates the cell's activities and growth."},{"id":"cytoplasm","label":"Cytoplasm","x":76,"y":32,"fact":"Where most of the cell's life processes happen."}]},{"id":"cheek","name":"Cheek Cell (Animal)","shape":"blob","hotspots":[{"id":"membrane","label":"Cell membrane","x":16,"y":50,"fact":"The porous outer boundary that controls what enters and exits the cell."},{"id":"nucleus","label":"Nucleus","x":50,"y":50,"fact":"Regulates the cell's activities and growth."},{"id":"cytoplasm","label":"Cytoplasm","x":72,"y":28,"fact":"Where most of the cell's life processes happen."}]}]}],"questions":[{"kind":"mcq","prompt":"Which structure did you see ONLY on the onion (plant) slide, not the cheek (animal) slide?","options":["Nucleus","Cytoplasm","Cell wall","Cell membrane"],"answer":2,"explain":"A rigid outer layer that gives the cell its fixed shape — found in plant cells but not animal cells."},{"kind":"sort","prompt":"Sort this structure into the correct bin.","item":"Nucleus","bins":["Found in both plant and animal cells","Found only in plant cells"],"answer":0,"explain":"The nucleus regulates cell activity and growth in every cell you looked at — plant or animal."}]},{"id":"mc2","title":"The Invisible World of Microbes","icon":"🧪","kind":"lesson","story":"Bacteria, algae, fungi, protozoa — microorganisms are everywhere: in pond water, in soil, even inside your gut. Some help us, some can harm us.","teach":[{"title":"Who are the microbes?","body":"Microorganisms are unicellular (bacteria, protozoa like Amoeba) or multicellular (some fungi, algae). Yeast is a unicellular fungus; bread mould is multicellular. Viruses are even smaller and can only multiply inside a living host cell.","visual":"🦠🍞🧬"},{"title":"Microbes at work","body":"Yeast releases carbon dioxide during respiration, making bread dough rise and turn fluffy. Lactobacillus bacteria ferment milk into curd, producing lactic acid. Rhizobium bacteria live in root nodules of legumes like peas and beans, trapping nitrogen from air to enrich the soil.","visual":"🍞🥛🌱"}],"questions":[{"kind":"mcq","prompt":"Which microorganism makes bread dough rise by releasing carbon dioxide?","options":["Rhizobium","Yeast","Amoeba","Paramecium"],"answer":1,"explain":"Yeast respires and releases carbon dioxide bubbles, making dough soft and fluffy."},{"kind":"fill","prompt":"The bacterium ______ turns milk into curd by producing lactic acid.","answer":"lactobacillus","placeholder":"bacterium name","explain":"Lactobacillus ferments the sugar (lactose) in milk into lactic acid, forming curd."},{"kind":"mcq","prompt":"Rhizobium bacteria living in the root nodules of legumes help the plant by...","options":["trapping nitrogen from the air","producing sugar","releasing oxygen only","breaking down rocks"],"answer":0,"explain":"Rhizobium traps nitrogen from the air, enriching the soil for the plant."}]},{"id":"mc-boss","title":"Guardian of the Petri Dish","icon":"🧬","kind":"boss","story":"Microorganisms decompose fallen leaves, dead plants and animal waste into nutrient-rich manure — a process called decomposition. Microalgae like Spirulina, Chlorella and Diatoms produce over half of Earth's oxygen.","teach":[{"title":"Nature's recyclers","body":"Microorganisms decompose fallen leaves, dead plants and animal waste into nutrient-rich manure — a process called decomposition. Microalgae like Spirulina, Chlorella and Diatoms produce more than half of Earth's oxygen supply and are used as food supplements.","visual":"🍂♻️🌾"}],"questions":[{"kind":"mcq","prompt":"The breakdown of dead plant and animal matter into nutrient-rich simpler substances is called...","options":["Fermentation","Decomposition","Photosynthesis","Respiration"],"answer":1,"explain":"Decomposition returns nutrients from dead matter back to the soil."},{"kind":"mcq","prompt":"Which of these produces more than half of Earth's oxygen supply?","options":["Bacteria","Microalgae","Viruses","Fungi"],"answer":1,"explain":"Microalgae like Spirulina and Chlorella produce over half the planet's oxygen."},{"kind":"tap","prompt":"Tap the option that is NOT a microorganism.","options":["Bacteria","Virus","Amoeba","Earthworm"],"answer":3,"explain":"An earthworm is a multicellular animal, visible to the naked eye — not a microorganism."},{"kind":"mcq","prompt":"The levels of organisation in a living body, from simplest to most complex, are:","options":["Organ → Tissue → Cell → Organism","Cell → Tissue → Organ → Organ system → Organism","Organism → Organ → Tissue → Cell","Tissue → Cell → Organ system → Organ"],"answer":1,"explain":"Cells group into tissues, tissues into organs, organs into organ systems, and systems form the whole organism."}],"boss":{"name":"The Decomposer King","taunt":"Without me, dead leaves and fallen fruit would never return to the soil. Do you even understand decomposition?"}}]},{"id":"vitality","index":3,"name":"The Health Vault","subtitle":"What keeps a body truly healthy","emoji":"🩺","theme":"Warm rose-red, glowing vitals, medical charts","palette":{"from":"#fb7185","to":"#e11d48","accent":"#881337"},"lessons":[{"id":"ht1","title":"What Does It Mean to Be Healthy?","icon":"💪","kind":"lesson","story":"The WHO says health isn't just 'not being sick' — it's complete physical, mental and social well-being. Let's find out how to protect it.","teach":[{"title":"More than not being sick","body":"According to the World Health Organization (WHO), health is a state of complete physical, mental, and social well-being — not merely the absence of disease. A balanced diet, exercise, cleanliness and a clean environment all help maintain it.","visual":"🥗🏃‍♀️🧼"},{"title":"Staying well","body":"Eating a balanced diet with fruits, vegetables and whole grains, exercising regularly, and keeping your surroundings clean are simple habits that protect your health every day.","visual":"🍎🚴🧹"}],"questions":[{"kind":"mcq","prompt":"According to WHO, health means...","options":["Never catching a cold","Complete physical, mental, and social well-being","Only having a strong body","Taking medicine regularly"],"answer":1,"explain":"WHO defines health as complete well-being, not merely the absence of disease."},{"kind":"tap","prompt":"Tap the option that is NOT one of the chapter's tips for staying healthy.","options":["Eat a balanced diet","Keep the environment clean","Skip exercise entirely","Get enough rest"],"answer":2,"explain":"Regular exercise, not skipping it, is one of the chapter's key tips."},{"kind":"fill","prompt":"WHO stands for World ______ Organization.","answer":"health","placeholder":"one word","explain":"WHO = World Health Organization."}]},{"id":"ht2","title":"Diseases: Causes and Spread","icon":"🦠","kind":"lesson","story":"Some diseases jump from person to person. Others quietly develop from within. Knowing the difference helps us fight both.","teach":[{"title":"Communicable vs non-communicable","body":"Communicable diseases are caused by pathogens (germs) and can spread from one person to another — through air, water, contaminated food, or insect bites like mosquitoes. Non-communicable diseases (NCDs) like diabetes and cancer are not caused by pathogens and don't spread between people.","visual":"🤧🚱🦟"},{"title":"Breaking the chain","body":"Washing hands with soap and water removes pathogens before they can spread. Good sanitation and hygiene are some of the most powerful tools against communicable diseases.","visual":"🧼🤝✅"}],"questions":[{"kind":"match","prompt":"Match each item correctly.","pairs":[["Communicable disease","Caused by pathogens, can spread between people"],["Non-communicable disease","Not caused by pathogens, doesn't spread"],["Mosquitoes","Can spread some pathogens between people"],["Washing hands","Simple way to remove pathogens"]],"explain":"Understanding how diseases spread is the first step in preventing them."},{"kind":"mcq","prompt":"Which of these is a non-communicable disease?","options":["Common cold","Diabetes","Chickenpox","Measles"],"answer":1,"explain":"Diabetes is not caused by a pathogen and does not spread between people."},{"kind":"mcq","prompt":"How can pathogens enter your body, according to the chapter?","options":["Only through food","Through air, contaminated water/food, insect bites, or contact","Only through insect bites","They cannot enter the body"],"answer":1,"explain":"Pathogens can enter through many routes: air, food, water, insects, or contact."},{"kind":"sort","prompt":"Sort this disease into the correct bin.","item":"Diabetes","bins":["Communicable disease","Non-communicable disease"],"answer":1,"explain":"Unlike the common cold, chickenpox or measles, diabetes cannot spread from person to person."}]},{"id":"ht-boss","title":"The Vaccine Trial","icon":"💉","kind":"boss","story":"A vaccine trains the immune system to recognise and attack a harmful germ, giving 'acquired immunity' — without causing the actual disease.","teach":[{"title":"How vaccines work","body":"A vaccine trains the immune system to recognise and attack a harmful germ, giving 'acquired immunity' — without causing the actual disease. Edward Jenner discovered that people exposed to cowpox did not get smallpox, leading to the world's first vaccine. Remember: vaccines are preventive, not curative.","visual":"💉🛡️🧬"}],"questions":[{"kind":"mcq","prompt":"Who discovered the first vaccine, based on observing that cowpox protected against smallpox?","options":["Louis Pasteur","Edward Jenner","Alexander Fleming","Robert Koch"],"answer":1,"explain":"Edward Jenner's cowpox observation led to the world's first vaccine."},{"kind":"mcq","prompt":"A vaccine works by...","options":["Curing a disease after you already have it","Training the immune system to recognise and fight a pathogen","Removing all germs from your body","Making you immune to every possible disease"],"answer":1,"explain":"Vaccines train the immune system in advance, before infection happens."},{"kind":"tap","prompt":"Tap the TRUE statement about vaccines.","options":["Vaccines are curative, not preventive","Vaccines are preventive, not curative","Vaccines work with no immune involvement","Only children can be vaccinated"],"answer":1,"explain":"Vaccines prevent disease — they don't cure a disease you already have."},{"kind":"fill","prompt":"The body's special defence system that fights disease is called the ______ system.","answer":"immune","placeholder":"one word","explain":"The immune system recognises and fights harmful pathogens."}],"boss":{"name":"Doubt, the Pathogen Lord","taunt":"Vaccines? Immunity? Prove you understand how your body truly defends itself!"}}]},{"id":"currentforge","index":4,"name":"Currents & Coils Forge","subtitle":"The magnetic and heating effects of electricity","emoji":"⚡","theme":"Amber sparks, coiled copper wire, glowing forge","palette":{"from":"#fbbf24","to":"#d97706","accent":"#78350f"},"lessons":[{"id":"el1","title":"The Magnetic Effect of Current","icon":"🧲","kind":"lesson","story":"Wrap a wire into a coil, pass current through it, and something magical happens — it behaves like a magnet!","teach":[{"title":"Current creates magnetism","body":"When electric current flows through a conductor like a wire, it produces a magnetic field around it — this is the magnetic effect of electric current. A current-carrying coil that behaves like a magnet is called an electromagnet.","visual":"🔌➡️🧲"},{"title":"Making a stronger electromagnet","body":"An electromagnet gets stronger if you increase the number of turns of the coil, increase the current flowing through it, or insert an iron core (like a nail) inside the coil.","visual":"🌀🔋🪛"}],"questions":[{"kind":"mcq","prompt":"A current-carrying coil that behaves like a magnet is called a/an...","options":["Dry cell","Electromagnet","Voltaic cell","Rechargeable battery"],"answer":1,"explain":"A coil carrying current that acts like a magnet is an electromagnet."},{"kind":"tap","prompt":"Tap the option that would NOT make an electromagnet stronger.","options":["Increasing the number of turns of the coil","Increasing the current through the coil","Inserting an iron core inside the coil","Removing all the wire turns"],"answer":3,"explain":"Removing the wire turns would destroy the electromagnet, not strengthen it."},{"kind":"mcq","prompt":"Unlike a permanent magnet, what special property does an electromagnet have?","options":["It can be switched on and off using current","It never loses its magnetism","It works without any wire","It can only attract wood"],"answer":0,"explain":"An electromagnet's magnetism depends on current flowing, so it can be switched on and off."},{"kind":"sort","prompt":"Sort this property into the correct bin.","item":"Electromagnet","bins":["Can be switched on and off using current","Always magnetic, even without current"],"answer":0,"explain":"Unlike a permanent magnet, an electromagnet's magnetism can be switched on and off using current."}]},{"id":"el2","title":"Heat from Current & How Batteries Work","icon":"🔋","kind":"lesson","story":"Ever wondered why a wire gets hot, or how a tiny battery can power your torch? It's all chemistry and current.","teach":[{"title":"The heating effect","body":"When electric current flows through a conductor, it generates heat — this is the heating effect of electric current. This is the working principle behind heaters, electric irons, and incandescent bulbs.","visual":"🔌🔥💡"},{"title":"How a cell generates current","body":"A cell or battery generates electric current through chemical reactions happening inside it. Dry cells are common in torches and remotes, while rechargeable batteries can be charged and reused many times over.","visual":"🔋⚗️♻️"}],"questions":[{"kind":"mcq","prompt":"The generation of heat in a conductor due to the flow of electric current is called...","options":["The magnetic effect","The heating effect of electric current","The chemical effect","The optical effect"],"answer":1,"explain":"This is the heating effect of electric current — it powers heaters and irons."},{"kind":"mcq","prompt":"A cell or battery generates electric current because of...","options":["Magnetic fields alone","Chemical reactions taking place inside it","Sunlight falling on it","Friction between its parts"],"answer":1,"explain":"Chemical reactions inside a cell generate the electric current it supplies."},{"kind":"fill","prompt":"A battery that can be charged and reused many times is called a ______ battery.","answer":"rechargeable","placeholder":"one word","explain":"Rechargeable batteries can be charged and reused repeatedly."}]},{"id":"el-boss","title":"The Circuit Breaker's Challenge","icon":"⚡","kind":"boss","story":"Electromagnets are used in electric motors, doorbells, and cranes that lift scrap metal. The heating effect powers toasters and heaters.","teach":[{"title":"Putting it together","body":"Electromagnets are used in electric motors, doorbells, and cranes that lift scrap metal because they can be switched on and off. The heating effect powers toasters and heaters. Both effects come from the same source: electric current flowing through a conductor.","visual":"🧲🔥🏗️"}],"questions":[{"kind":"match","prompt":"Match each effect to its use.","pairs":[["Magnetic effect","Used in electromagnets and motors"],["Heating effect","Used in heaters and toasters"],["Chemical reaction inside a cell","Generates electric current"],["Iron core in a coil","Makes an electromagnet stronger"]],"explain":"Electricity's magnetic and heating effects power very different everyday devices."},{"kind":"mcq","prompt":"Cranes that lift and drop scrap iron rely mainly on an electromagnet's ability to...","options":["Be switched on and off using current","Stay magnetic forever, even with no current","Generate heat","Change colour"],"answer":0,"explain":"Switching the current off releases the scrap metal — a key advantage of electromagnets."},{"kind":"mcq","prompt":"Compared to a dry cell, a rechargeable battery's main advantage is that it...","options":["Never generates current","Can be charged and reused many times","Cannot power any device","Uses no chemical reactions"],"answer":1,"explain":"Rechargeable batteries can be recharged and reused, unlike single-use dry cells."},{"kind":"tap","prompt":"Tap the TRUE statement.","options":["Electric current cannot produce a magnetic field","A current-carrying wire produces a magnetic field around it","Batteries generate current from sunlight","Heat is never produced by electric current"],"answer":1,"explain":"A current-carrying conductor always produces a magnetic field around it."}],"boss":{"name":"Sparky, Lord of Short Circuits","taunt":"Currents, coils, and chemistry — think you can outsmart the forge?"}}]},{"id":"forcefield","index":5,"name":"The Force Frontier","subtitle":"Pushes, pulls, friction, and gravity","emoji":"🥊","theme":"Violet energy fields, motion trails, dynamic arrows","palette":{"from":"#a78bfa","to":"#7c3aed","accent":"#4c1d95"},"lessons":[{"id":"fc1","title":"What Is a Force?","icon":"👊","kind":"lesson","story":"A push, a pull, a tug-of-war — every single one is a force. But forces always come from an interaction between two objects.","teach":[{"title":"Push, pull, interact","body":"A force is a push or pull on an object resulting from its interaction with another object. The SI unit of force is the newton (N). A force can change an object's speed, its direction of motion, or its shape.","visual":"👉⬅️📏"},{"title":"Contact vs non-contact","body":"Contact forces need touching — like muscular force and frictional force. Non-contact forces act at a distance — like magnetic force, gravitational force, and electrostatic force.","visual":"🤝🧲🌍"}],"questions":[{"kind":"mcq","prompt":"What is the SI unit of force?","options":["Kilogram","Newton","Joule","Metre"],"answer":1,"explain":"Force is measured in newtons (N)."},{"kind":"match","prompt":"Match each force to its type.","pairs":[["Muscular force","A contact force"],["Frictional force","A contact force"],["Magnetic force","A non-contact force"],["Gravitational force","A non-contact force"]],"explain":"Contact forces require touching; non-contact forces act at a distance."},{"kind":"mcq","prompt":"A force acting on an object can change...","options":["Only its speed","Only its shape","Its speed, direction, or shape","None of these"],"answer":2,"explain":"Forces can change speed, direction of motion, or even the shape of an object."}]},{"id":"fc2","title":"Friction, Gravity & Weight","icon":"⚖️","kind":"lesson","story":"Why does a ball rolling on the ground eventually stop? And why do objects fall back to Earth every single time?","teach":[{"title":"Friction opposes motion","body":"Friction is the force that comes into play when an object moves or tries to move over another surface. It always acts opposite to the direction of motion — which is why a rolling ball eventually slows down and stops.","visual":"⚽🛑↩️"},{"title":"Gravity and weight","body":"Gravitational force is the force with which Earth attracts objects towards itself — it is always attractive. The force with which Earth pulls an object is called its weight, measured in newtons. Mass never changes, but weight can vary from place to place.","visual":"🍎⬇️🌍"}],"questions":[{"kind":"mcq","prompt":"Friction acts in a direction...","options":["Same as the direction of motion","Opposite to the direction of motion or attempted motion","Always upward","Always sideways"],"answer":1,"explain":"Friction always opposes the direction of motion or attempted motion."},{"kind":"mcq","prompt":"Which stays constant no matter where an object is, while its weight can change?","options":["Weight","Mass","Force","Newton"],"answer":1,"explain":"Mass stays the same everywhere; weight depends on gravitational pull, which can vary."},{"kind":"fill","prompt":"The force with which the Earth attracts objects towards itself is called ______ force.","answer":"gravitational","placeholder":"one word","explain":"Gravitational force always pulls objects towards the Earth."}]},{"id":"fc-boss","title":"The Buoyancy Trial","icon":"🛟","kind":"boss","story":"A coin sinks. A massive ship floats. When an object is placed in a liquid, the liquid pushes back with an upward force.","teach":[{"title":"Floating and sinking","body":"When an object is placed in a liquid, the liquid pushes back on it with an upward force called upthrust or buoyant force. Whether an object floats or sinks depends on the balance between its weight and this upthrust.","visual":"🚢⚓⬆️"}],"questions":[{"kind":"mcq","prompt":"The upward force exerted by a liquid on an object placed in it is called...","options":["Gravitational force","Upthrust or buoyant force","Frictional force","Electrostatic force"],"answer":1,"explain":"Upthrust, or buoyant force, is the liquid's upward push on an object."},{"kind":"mcq","prompt":"A coin sinks in water but a large wooden block floats — why, broadly speaking?","options":["Wood has no weight","The block experiences enough upthrust to balance its weight, the coin doesn't","Coins are magnetic","Wood dissolves in water"],"answer":1,"explain":"Floating happens when upthrust is enough to balance the object's weight."},{"kind":"sort","prompt":"Sort this force into the correct bin.","item":"Gravitational force","bins":["Contact force","Non-contact force"],"answer":1,"explain":"Gravitational force acts at a distance, without any contact needed."},{"kind":"mcq","prompt":"A ball thrown straight up eventually falls back down mainly because of...","options":["Friction from the air alone","Gravitational force pulling it back to Earth","Magnetic force","Electrostatic force"],"answer":1,"explain":"Gravity constantly pulls the ball back towards the Earth."}],"boss":{"name":"Archimedes' Echo","taunt":"A coin sinks. A massive ship floats. Explain that, if you dare!"}}]},{"id":"skystorm","index":6,"name":"Pressure Peaks & Storm Chasers","subtitle":"Pressure, wind, thunderstorms, and cyclones","emoji":"🌪️","theme":"Storm-grey clouds, lightning flashes, swirling wind","palette":{"from":"#94a3b8","to":"#475569","accent":"#1e293b"},"lessons":[{"id":"pr1","title":"Pressure and Air","icon":"💨","kind":"lesson","story":"Push a drawing pin with your thumb and it hurts — but the flat side doesn't. Why? It's all about area.","teach":[{"title":"Force per unit area","body":"Pressure is defined as force per unit area. Its SI unit is newton per square metre (N/m2), also called the pascal (Pa). The same force spread over a smaller area creates greater pressure.","visual":"📌👍📐"},{"title":"Air has pressure too","body":"The pressure exerted by the air around us is called atmospheric pressure. Liquids and gases both exert pressure on the walls of whatever contains them.","visual":"🌬️🫧🧴"}],"questions":[{"kind":"mcq","prompt":"Pressure is defined as...","options":["Force multiplied by area","Force per unit area","Mass per unit volume","Energy per unit time"],"answer":1,"explain":"Pressure = Force / Area."},{"kind":"mcq","prompt":"The SI unit of pressure, newton per square metre, is also called the...","options":["Joule","Pascal","Watt","Newton"],"answer":1,"explain":"Pressure is measured in pascals (Pa), where 1 Pa = 1 N/m2."},{"kind":"fill","prompt":"The pressure exerted by the air around us is called ______ pressure.","answer":"atmospheric","placeholder":"one word","explain":"Atmospheric pressure is the pressure exerted by the air surrounding us."}]},{"id":"pr2","title":"Winds, Thunderstorms & Lightning","icon":"⛈️","kind":"lesson","story":"Warm air rises, cool air rushes in to replace it — and that's how a gentle breeze is born. But sometimes, it grows into something much fiercer.","teach":[{"title":"How wind forms","body":"Warm air rises, creating a low-pressure area. Cooler air from surrounding higher-pressure regions rushes in to take its place — this movement of air is wind. Bigger pressure differences create stronger winds.","visual":"🔥⬆️🌬️"},{"title":"Thunderstorms and lightning","body":"Thunderstorms need moisture and strong winds. As strong winds move ice particles and water droplets up and down, they rub together and build up electric charge in the clouds. When these charges collide, lightning strikes.","visual":"💧⚡☁️"}],"questions":[{"kind":"mcq","prompt":"Wind is caused by air moving from...","options":["Low pressure to high pressure","High pressure to low pressure","There is no pattern","Only from north to south"],"answer":1,"explain":"Air always moves from a region of higher pressure to a region of lower pressure."},{"kind":"mcq","prompt":"What two ingredients does the chapter say are important for thunderstorm formation?","options":["Moisture and strong winds","Dry air and stillness","Cold air and no wind","Sunlight and dust only"],"answer":0,"explain":"Thunderstorms require both moisture and strong winds."},{"kind":"tap","prompt":"Tap the safety device that protects buildings from lightning.","options":["Umbrella","Lightning conductor","Fan","Air conditioner"],"answer":1,"explain":"A lightning conductor safely channels a lightning strike into the ground."},{"kind":"sort","prompt":"Sort this into the correct bin.","item":"Wind","bins":["Moves from high pressure to low pressure","Moves from low pressure to high pressure"],"answer":0,"explain":"Wind is air moving from a region of high pressure to a region of low pressure."}]},{"id":"pr-boss","title":"Eye of the Cyclone","icon":"🌀","kind":"boss","story":"A cyclone is a large system of very strong, rotating winds around a low-pressure centre.","teach":[{"title":"Cyclones","body":"A cyclone is a large system of very strong, rotating winds around a low-pressure centre. The India Meteorological Department (IMD) constantly monitors cyclones and thunderstorms across India to warn and protect people.","visual":"🌀🛰️🇮🇳"}],"questions":[{"kind":"numeric","prompt":"An elephant's four feet together cover an area of 1 m2 and it weighs 20000 N. Using Pressure = Force / Area, what pressure (in N/m2) does it exert on the ground?","answer":20000,"placeholder":"N/m2","explain":"Pressure = Force / Area = 20000 N / 1 m2 = 20000 N/m2."},{"kind":"mcq","prompt":"Which organisation constantly monitors cyclones and thunderstorms in India?","options":["ISRO","India Meteorological Department (IMD)","NASA","WHO"],"answer":1,"explain":"The IMD monitors and warns about cyclones and storms across India."},{"kind":"tap","prompt":"Tap the TRUE statement.","options":["Liquids exert pressure only at the bottom of a container","Liquids exert pressure on all the walls of their container","Air never exerts pressure","Wind always blows from low to high pressure"],"answer":1,"explain":"Liquids press on all the walls of their container, not just the bottom."},{"kind":"mcq","prompt":"According to the chapter, during a thunderstorm it is considered relatively safer to be...","options":["Standing under a tall tree","Inside a car","Standing in an open field","Holding a metal rod outside"],"answer":1,"explain":"The chapter notes it is safer to be inside a car during a thunderstorm."}],"boss":{"name":"The Cyclone Sentinel","taunt":"Storms bow to no one who doesn't understand pressure!"}}]},{"id":"particlerealm","index":7,"name":"The Particle Dimension","subtitle":"The particulate nature of matter","emoji":"⚛️","theme":"Pink-violet quantum haze, tiny glowing dots, vibrating fields","palette":{"from":"#f472b6","to":"#c026d3","accent":"#701a75"},"lessons":[{"id":"pt1","title":"Matter Is Made of Particles","icon":"⚛️","kind":"lesson","story":"Zoom in far enough on anything — a rock, water, air — and you'll find it's built from countless tiny particles, all held together by invisible forces.","teach":[{"title":"Interparticle forces","body":"Matter is composed of extremely small particles, held together by interparticle forces of attraction. These attractive forces are strongest in solids, a little weaker in liquids, and weakest in gases.","visual":"🧱💧🎈"},{"title":"Why states differ","body":"Solids have a fixed shape and size because of strong interparticle attraction, minimum spacing, and no free movement. Liquids have a definite volume but no fixed shape. Gases have no fixed shape or volume — their particles move around freely.","visual":"🧊〰️💨"}],"questions":[{"kind":"mcq","prompt":"In which state of matter are interparticle attractive forces the strongest?","options":["Gas","Liquid","Solid","They're always equal"],"answer":2,"explain":"Interparticle attraction is strongest in solids, which is why they hold a fixed shape."},{"kind":"match","prompt":"Match each state of matter to its property.","pairs":[["Solid","Fixed shape and fixed volume"],["Liquid","No fixed shape but definite volume"],["Gas","No fixed shape and no fixed volume"]],"explain":"Each state's behaviour comes from how strongly its particles attract each other."},{"kind":"mcq","prompt":"Why do solids have a fixed shape?","options":["Their particles move freely","Strong interparticle attraction keeps particles from moving much","They have no interparticle forces at all","Their particles are very far apart"],"answer":1,"explain":"Strong attraction locks solid particles into place, giving them a fixed shape."},{"kind":"sort","prompt":"Sort this state of matter into the correct bin.","item":"Gas","bins":["Weak interparticle forces","Strong interparticle forces"],"answer":0,"explain":"Solids have the strongest interparticle attraction; gases have the weakest, letting their particles move freely."}]},{"id":"pt2","title":"Diffusion and Change of State","icon":"🌬️","kind":"lesson","story":"Why can you smell perfume from across the room, or watch sugar vanish into hot tea faster than cold tea?","teach":[{"title":"Particles are always moving","body":"Even in solids, particles vibrate about a fixed position. In liquids they move more freely, and in gases they move fastest and spread out to fill any container — this spreading is called diffusion. Heating gives particles more energy, so they move faster.","visual":"🫨〰️💨"},{"title":"From solid to gas and back","body":"When ice melts to water, and water evaporates to vapour, the particles gain energy and move apart from each other. Interparticle spacing increases at every step: solid → liquid → gas.","visual":"🧊➡️💧➡️💨"}],"questions":[{"kind":"mcq","prompt":"The spreading of particles of one substance into another, like the smell of camphor filling a room, is called...","options":["Condensation","Diffusion","Freezing","Compression"],"answer":1,"explain":"Diffusion is the spontaneous spreading of particles, like a scent filling a room."},{"kind":"mcq","prompt":"As a solid melts into a liquid and then evaporates into a gas, interparticle spacing...","options":["Decreases at every step","Stays exactly the same","Increases at every step","Becomes zero"],"answer":2,"explain":"Spacing between particles increases as matter goes from solid to liquid to gas."},{"kind":"tap","prompt":"Tap the TRUE statement about particles of matter.","options":["Gases mix easily because their particles move freely with large gaps between them","Solids mix as easily as gases","Particles in a solid never move at all","There are no particles in a liquid"],"answer":0,"explain":"Gas particles move freely with large gaps, so different gases mix easily."}]},{"id":"pt-boss","title":"The Vanishing Point","icon":"🔎","kind":"boss","story":"Even when dissolved salt is invisible in ocean water, its particles are still there, mixed uniformly among the water particles.","teach":[{"title":"Why the ocean tastes salty","body":"Even when dissolved salt is invisible in ocean water, its particles are still there, mixed uniformly among the water particles — which is why the water tastes salty even though you can't see the salt.","visual":"🌊🧂👁️"}],"questions":[{"kind":"mcq","prompt":"If we could remove all the constituent particles from a chair, what would happen?","options":["Nothing would change","Nothing of the chair would remain","The chair would become heavier","The chair would turn into gas but keep its shape"],"answer":1,"explain":"The chair itself is entirely made of particles — remove them all, and nothing remains."},{"kind":"mcq","prompt":"Why does ocean water taste salty even though you can't see any salt in it?","options":["The salt evaporated","Dissolved salt particles are mixed uniformly with water particles, too small to see","The ocean has no salt, it's an illusion","Fish make the water taste salty"],"answer":1,"explain":"Dissolved salt particles are too small to see but are still present throughout the water."},{"kind":"order","prompt":"Order these states of matter from strongest to weakest interparticle attraction.","items":["Gas","Liquid","Solid"],"answer":["Solid","Liquid","Gas"],"explain":"Interparticle attraction is strongest in solids, weaker in liquids, weakest in gases."},{"kind":"mcq","prompt":"Grains of rice and rice flour both take the shape of whatever jar they're poured into. What does this tell us?","options":["They are liquids in the same sense as water","Each individual grain is solid, but as a collection they can flow and settle into the container's shape","They have no particles","They are gases"],"answer":1,"explain":"Individual solid grains can still flow as a group and take a container's shape."}],"boss":{"name":"The Interparticle Sentinel","taunt":"If I removed every particle from this chair, what would remain? Answer, or be scattered like gas!"}}]},{"id":"elementatlas","index":8,"name":"Elements & Mixtures Atlas","subtitle":"Elements, compounds, and mixtures","emoji":"🧪","theme":"Teal chemistry glow, periodic-table shimmer, glassware","palette":{"from":"#2dd4bf","to":"#0d9488","accent":"#134e4a"},"lessons":[{"id":"em1","title":"Mixtures and Pure Substances","icon":"🥤","kind":"lesson","story":"Salt water, air, and granite are all mixtures — but a bar of pure gold isn't. What separates the two?","teach":[{"title":"What is a mixture?","body":"A mixture consists of two or more substances mixed together. These substances (called components) retain their individual properties and do not react chemically with each other. Air itself is a mixture of gases like nitrogen and oxygen.","visual":"🌬️🧂💧"},{"title":"Pure substances","body":"A pure substance consists of only one type of particle, and all its constituent particles behave identically. Pure substances are either elements or compounds.","visual":"🥇⚗️"}],"questions":[{"kind":"mcq","prompt":"In a mixture, the substances that make it up...","options":["Always react chemically with each other","Retain their individual properties without reacting chemically","Turn into a completely new pure substance","Cannot ever be separated"],"answer":1,"explain":"Components of a mixture keep their own properties and don't react chemically."},{"kind":"sort","prompt":"Sort this substance into the correct bin.","item":"Air (mainly nitrogen and oxygen gases)","bins":["Pure substance","Mixture"],"answer":1,"explain":"Air is a mixture of gases, mainly nitrogen and oxygen."},{"kind":"fill","prompt":"A pure substance is either an element or a ______.","answer":"compound","placeholder":"one word","explain":"Pure substances are classified as elements or compounds."}]},{"id":"em2","title":"Elements, Compounds, and Minerals","icon":"💎","kind":"lesson","story":"Gold is an element. Water is a compound. Granite is a mixture of minerals. Let's tell them apart.","teach":[{"title":"Elements vs compounds","body":"Elements are the simplest substances that cannot be broken down further into simpler substances — they're the building blocks of all matter. Compounds are made of two or more elements combined chemically in a fixed ratio, with properties completely different from their constituent elements.","visual":"⚛️➕⚗️"},{"title":"Minerals","body":"Minerals are natural, solid substances found on Earth with a fixed chemical composition. Most minerals are compounds, though a few — like pure gold — can be elements themselves.","visual":"💎⛏️"}],"questions":[{"kind":"mcq","prompt":"A substance that cannot be broken down further into simpler substances is called a/an...","options":["Mixture","Element","Solution","Suspension"],"answer":1,"explain":"Elements are the simplest substances and cannot be broken down further."},{"kind":"mcq","prompt":"Compounds are formed when two or more elements combine...","options":["Physically, in any random ratio","Chemically, in a fixed ratio","Only when heated to extreme temperatures","Only in liquid form"],"answer":1,"explain":"Compounds form via chemical combination of elements in a fixed ratio."},{"kind":"tap","prompt":"Tap the TRUE statement about minerals.","options":["All minerals are elements","Most minerals are compounds, though a few are pure elements","Minerals are always man-made","Minerals have no fixed composition"],"answer":1,"explain":"Most minerals are compounds, though a few, like gold, are pure elements."}]},{"id":"em-boss","title":"The Classification Trial","icon":"🧫","kind":"boss","story":"Element, compound, or mixture? Every material around you can be classified using these three categories.","teach":[{"title":"Putting substances in their place","body":"Every material around you can be classified: is it a pure substance (element or compound) or a mixture? This classification is one of the most powerful tools in science for understanding matter.","visual":"🗂️🧪✅"}],"questions":[{"kind":"match","prompt":"Match each substance to its category.","pairs":[["Gold","Element"],["Water","Compound"],["Salt water","Mixture"],["Air","Mixture"]],"explain":"Sorting substances into elements, compounds, and mixtures is a core chemistry skill."},{"kind":"mcq","prompt":"Which of these best describes a compound's properties compared to its elements?","options":["Identical to its elements","Completely different from its constituent elements","Always heavier than its elements","Always a gas"],"answer":1,"explain":"A compound's properties differ completely from the elements that form it."},{"kind":"sort","prompt":"Sort this substance into the correct bin.","item":"Granite","bins":["Pure substance","Mixture"],"answer":1,"explain":"Granite is a mixture of several different minerals."},{"kind":"mcq","prompt":"Matter can first be classified into pure substances and mixtures. Pure substances are then divided into...","options":["Solids and liquids","Elements and compounds","Metals and non-metals","Acids and bases"],"answer":1,"explain":"Pure substances split further into elements and compounds."}],"boss":{"name":"The Sorting Alchemist","taunt":"Element, compound, or mixture? Sort wrong, and chaos reigns in my lab!"}}]},{"id":"solutionlab","index":9,"name":"The Solution Laboratory","subtitle":"Solutes, solvents, solubility, and density","emoji":"🧪","theme":"Cyan liquid swirls, dissolving crystals, measuring cylinders","palette":{"from":"#22d3ee","to":"#0891b2","accent":"#164e63"},"lessons":[{"id":"sl1","title":"Solute, Solvent, and Solubility","icon":"🥄","kind":"lesson","story":"Stir sugar into tea and it disappears — but keep adding more, and eventually it stops dissolving. Where's the limit?","teach":[{"title":"Solute + solvent = solution","body":"When a solid dissolves in a liquid, the solid is the solute and the liquid is the solvent. When two liquids mix, whichever is present in smaller quantity is the solute. Together they form a solution.","visual":"🧂➕💧=🥤"},{"title":"Saturated or not?","body":"A saturated solution has dissolved the maximum amount of solute possible at that temperature — no more will dissolve. An unsaturated solution can still dissolve more solute. Solubility is the maximum amount of solute that dissolves in a fixed amount (100 mL) of solvent at a given temperature.","visual":"🥤🚫➕"}],"questions":[{"kind":"mcq","prompt":"When sugar dissolves in water, which is the solute and which is the solvent?","options":["Sugar is the solvent, water is the solute","Sugar is the solute, water is the solvent","Both are solutes","Neither is a solute"],"answer":1,"explain":"The dissolved solid (sugar) is the solute; the liquid (water) is the solvent."},{"kind":"mcq","prompt":"A solution that has dissolved the maximum solute possible at a given temperature, with no more able to dissolve, is called...","options":["Unsaturated","Saturated","Diluted","Concentrated only"],"answer":1,"explain":"A saturated solution cannot dissolve any more solute at that temperature."},{"kind":"mcq","prompt":"Generally, as temperature increases, the solubility of a solid in a liquid tends to...","options":["Decrease","Increase","Stay exactly the same always","Become zero"],"answer":1,"explain":"Solids generally dissolve more easily as the liquid's temperature rises."}]},{"id":"sl2","title":"Density: Why Things Float or Sink","icon":"🧊","kind":"lesson","story":"An ice cube floats in your drink, but a coin sinks straight to the bottom. It all comes down to density.","teach":[{"title":"Mass, volume, density","body":"Mass is the amount of matter in an object; volume is the space it occupies. Density is mass per unit volume: Density = Mass / Volume. Mass is measured with a weighing balance, and volume with a measuring cylinder.","visual":"⚖️📏🧮"},{"title":"Floating and sinking","body":"An object floats in water if its density is less than water's density, and sinks if its density is greater. Generally, density decreases as temperature increases, since matter expands slightly when heated.","visual":"🧊🪙⬇️"}],"questions":[{"kind":"fill","prompt":"Density equals mass divided by ______.","answer":"volume","placeholder":"one word","explain":"Density = Mass / Volume."},{"kind":"mcq","prompt":"As temperature generally increases, the density of a substance tends to...","options":["Increase","Decrease","Stay exactly the same","Become negative"],"answer":1,"explain":"Substances usually expand slightly when heated, which decreases their density."},{"kind":"mcq","prompt":"Solubility of a gas in a liquid, as temperature increases, generally...","options":["Increases","Decreases","Stays exactly the same","Becomes infinite"],"answer":1,"explain":"Unlike solids, gases generally become less soluble in liquids as temperature rises."}]},{"id":"sl-boss","title":"The Density Duel","icon":"⚖️","kind":"boss","story":"Whether a solid dissolves, how much can dissolve, and whether an object floats or sinks — it all comes down to solute, solvent, solubility, and density.","teach":[{"title":"Bringing it together","body":"Whether a solid dissolves, how much of it can dissolve, and whether an object floats or sinks in a liquid — all of it comes down to the same core ideas: solute, solvent, solubility, and density.","visual":"🧪⚖️🌊"}],"questions":[{"kind":"numeric","prompt":"A block has a mass of 50 g and a volume of 10 mL. Using Density = Mass / Volume, what is its density in g/mL?","answer":5,"placeholder":"g/mL","explain":"Density = 50 g / 10 mL = 5 g/mL."},{"kind":"mcq","prompt":"Devices used to measure mass and volume are, respectively...","options":["Measuring cylinder and weighing balance","Weighing balance and measuring cylinder","Thermometer and weighing balance","Measuring cylinder and thermometer"],"answer":1,"explain":"Mass is measured with a weighing balance; volume with a measuring cylinder."},{"kind":"tap","prompt":"Tap the TRUE statement.","options":["An unsaturated solution can dissolve more solute","A saturated solution can always dissolve more solute","Solubility never depends on temperature","Density has nothing to do with floating or sinking"],"answer":0,"explain":"An unsaturated solution still has room to dissolve more solute."},{"kind":"mcq","prompt":"If an object's density is greater than the density of water, the object will...","options":["Float","Sink","Dissolve completely","Evaporate"],"answer":1,"explain":"An object denser than water sinks, since it's not buoyed up enough to float."},{"kind":"sort","prompt":"Sort this object into the correct bin.","item":"An object denser than water","bins":["Floats","Sinks"],"answer":1,"explain":"If an object's density is greater than the density of water, it sinks."}],"boss":{"name":"The Solubility Sphinx","taunt":"Sink or float? Dissolve or settle? Answer correctly, or be diluted into nothingness!"}}]},{"id":"lightworks","index":10,"name":"The Mirror & Lens Observatory","subtitle":"Mirrors, lenses, and the laws of reflection","emoji":"🔦","theme":"Golden light beams, mirrored glass, focused rays","palette":{"from":"#fef08a","to":"#eab308","accent":"#713f12"},"lessons":[{"id":"lt1","title":"Concave and Convex Mirrors","icon":"🪞","kind":"lesson","story":"A dentist's mirror enlarges your teeth. A car's side mirror shrinks the traffic behind you. Same light, different curves.","teach":[{"title":"Two kinds of spherical mirrors","body":"A mirror whose reflecting surface curves inward is a concave mirror. One that curves outward is a convex mirror. A plane mirror always forms an erect image the same size as the object — but spherical mirrors behave differently.","visual":"🪞⬅️➡️"},{"title":"How their images differ","body":"A concave mirror can form an enlarged, erect image when the object is close, but as the object moves away, the image shrinks and eventually inverts. A convex mirror always forms an erect, smaller (diminished) image, no matter the distance.","visual":"🦷🚗🔍"}],"questions":[{"kind":"mcq","prompt":"A mirror whose reflecting surface curves inward is called a...","options":["Convex mirror","Concave mirror","Plane mirror","Diverging mirror"],"answer":1,"explain":"A concave mirror's reflecting surface curves inward."},{"kind":"mcq","prompt":"A dentist's mirror, which gives an enlarged view of teeth, is a...","options":["Convex mirror","Plane mirror","Concave mirror","Diverging lens"],"answer":2,"explain":"Concave mirrors can form enlarged images of nearby objects, useful for dentists."},{"kind":"mcq","prompt":"A convex mirror used as a vehicle's side mirror always forms an image that is...","options":["Inverted and enlarged","Erect and smaller than the object","Erect and larger than the object","Upside down and the same size"],"answer":1,"explain":"Convex mirrors always form erect, diminished images — giving a wider view of traffic."}]},{"id":"lt2","title":"The Laws of Reflection & Lenses","icon":"📐","kind":"lesson","story":"Bounce a ray of light off a mirror, and it obeys a strict rule every single time — the same rule light has followed since Grade 7.","teach":[{"title":"The law of reflection","body":"The angle of incidence (i) always equals the angle of reflection (r). The incident ray, the reflected ray, and the normal all lie in the same plane. This is the law of reflection.","visual":"↘️↗️📏"},{"title":"Convex and concave lenses","body":"A lens thicker at the middle than the edges is a convex lens — it converges (brings together) light, so it's also called a converging lens. A lens thicker at the edges than the middle is a concave lens — it diverges light, so it's called a diverging lens.","visual":"🔍🔦↔️"}],"questions":[{"kind":"mcq","prompt":"According to the law of reflection, the angle of incidence is...","options":["Always greater than the angle of reflection","Always less than the angle of reflection","Always equal to the angle of reflection","Unrelated to the angle of reflection"],"answer":2,"explain":"The law of reflection states the angle of incidence always equals the angle of reflection."},{"kind":"mcq","prompt":"A convex lens is also known as a...","options":["Diverging lens","Converging lens","Plane lens","Concave lens"],"answer":1,"explain":"A convex lens converges light to a point, so it's called a converging lens."},{"kind":"tap","prompt":"Tap the lens that is thicker at the edges than in the middle.","options":["Convex lens","Concave lens","Plane mirror","Concave mirror"],"answer":1,"explain":"A concave lens is thinner in the middle and thicker at the edges."},{"kind":"sort","prompt":"Sort this lens into the correct bin.","item":"Convex lens","bins":["Converging lens","Diverging lens"],"answer":0,"explain":"A convex lens is also known as a converging lens, since it brings light rays together."}]},{"id":"lt-boss","title":"The Reflection Riddle","icon":"🔭","kind":"boss","story":"Concave mirrors focus light in torches, headlights, and telescopes. Convex mirrors give wide-angle views for safety and security.","teach":[{"title":"Light all around us","body":"Concave mirrors focus light in torches, headlights, and telescopes. Convex mirrors give wide-angle views in store security and road-safety mirrors. Convex lenses converge sunlight to a point — never look at the Sun directly through one, as it can damage your eyes.","visual":"🔦🛰️⚠️"}],"questions":[{"kind":"mcq","prompt":"The reflectors used in torches and car headlights are usually...","options":["Convex mirrors","Concave mirrors","Plane mirrors","Concave lenses"],"answer":1,"explain":"Concave mirrors focus light into a strong, directed beam, ideal for torches and headlights."},{"kind":"mcq","prompt":"Why should you never look at the Sun directly through a convex lens?","options":["It has no effect","The lens converges sunlight to a point, which can damage your eyes","Convex lenses block all light","It will make the Sun look smaller"],"answer":1,"explain":"A convex lens focuses sunlight to an intense point, which can seriously damage your eyes."},{"kind":"tap","prompt":"Tap the TRUE statement.","options":["A concave lens converges light","A convex lens converges light while a concave lens diverges it","Lenses reflect light instead of allowing it to pass through","Mirrors let light pass through them"],"answer":1,"explain":"Convex lenses converge light; concave lenses diverge it."},{"kind":"mcq","prompt":"Wide-angle convex mirrors are installed at road intersections mainly to...","options":["Make cars look bigger","Give drivers a wider view of oncoming traffic and prevent collisions","Block sunlight","Decorate the street"],"answer":1,"explain":"Convex mirrors give a wider field of view, helping prevent collisions at blind corners."}],"boss":{"name":"The Keeper of Angles","taunt":"Light bends to my laws. Prove you know them, or stay in the dark!"}}]},{"id":"skywatch","index":11,"name":"Skywatcher's Calendar","subtitle":"Moon phases, calendars, and satellites","emoji":"🌙","theme":"Deep indigo night sky, glowing moon phases, starlight","palette":{"from":"#818cf8","to":"#4338ca","accent":"#1e1b4b"},"lessons":[{"id":"sk1","title":"Phases of the Moon","icon":"🌗","kind":"lesson","story":"Every night the Moon looks a little different — full, half, a sliver, or gone entirely. But the Moon isn't actually changing shape.","teach":[{"title":"Why the Moon changes shape","body":"The Moon doesn't produce its own light — it reflects sunlight. As the Moon orbits Earth, we see different portions of its sunlit half, which is why its illuminated shape appears to change — these are the phases of the Moon, from new Moon to crescent to full Moon.","visual":"🌑🌓🌕"},{"title":"One full cycle","body":"A complete cycle of the Moon's phases — from one new Moon to the next — takes about a month (roughly 29.5 days).","visual":"🌒🌖🔁"}],"questions":[{"kind":"mcq","prompt":"Why does the Moon's illuminated shape appear to change through the month?","options":["The Moon changes its actual shape","We see different portions of its sunlit half as it orbits Earth","The Moon turns off its own light","Clouds cover parts of it"],"answer":1,"explain":"We see varying portions of the Moon's sunlit half as it orbits the Earth."},{"kind":"mcq","prompt":"About how long does one full cycle of the Moon's phases take?","options":["One day","About a week","About a month","About a year"],"answer":2,"explain":"A full cycle of lunar phases takes about a month (roughly 29.5 days)."},{"kind":"fill","prompt":"The Moon does not produce its own light — it reflects light from the ______.","answer":"sun","placeholder":"one word","explain":"The Moon shines because it reflects sunlight."}]},{"id":"sk2","title":"Calendars Written in the Sky","icon":"📅","kind":"lesson","story":"Long before smartphones, humans tracked the sky itself to know when to plant crops or celebrate festivals.","teach":[{"title":"Three kinds of calendars","body":"Lunar calendars follow the Moon's phase cycle. Solar calendars follow the cycle of seasons, based on Earth's position as it orbits the Sun. Luni-solar calendars combine and adapt to both cycles at once.","visual":"🌙☀️📆"},{"title":"India's National Calendar","body":"India uses the Indian National Calendar (Saka calendar) alongside the widely used Gregorian calendar. Many Indian festivals are tied to specific astronomical events, like the position of the Moon or the Sun.","visual":"🇮🇳🗓️🎉"}],"questions":[{"kind":"match","prompt":"Match each calendar type to what it follows.","pairs":[["Lunar calendar","Follows the Moon's cycle"],["Solar calendar","Follows the cycle of seasons / Earth's orbit"],["Luni-solar calendar","Adapts to both the Moon and Sun cycles"]],"explain":"Different calendars are built around different astronomical cycles."},{"kind":"mcq","prompt":"What does India's National Calendar run alongside?","options":["No other calendar is used","The widely used Gregorian calendar","Only the lunar calendar","Only the solar calendar"],"answer":1,"explain":"India's National (Saka) Calendar is used alongside the Gregorian calendar."},{"kind":"mcq","prompt":"The various cycles observed in nature — like the Moon's phases and the seasons — led humans to create...","options":["Clocks","Calendars","Telescopes","Satellites"],"answer":1,"explain":"Observing natural cycles led ancient humans to invent calendars."}]},{"id":"sk-boss","title":"The Satellite Ascension","icon":"🛰️","kind":"boss","story":"Artificial satellites are human-made objects launched from Earth, providing crucial information for our well-being and space-science research.","teach":[{"title":"Why we launch satellites","body":"Artificial satellites are human-made objects launched from Earth. They provide crucial information for weather forecasting, communication, navigation, and space-science research that supports our well-being on the ground.","visual":"🛰️📡🌍"}],"questions":[{"kind":"mcq","prompt":"Artificial satellites are launched mainly to...","options":["Replace the Moon","Provide important information for our well-being and space-science studies","Decorate the night sky","Block sunlight"],"answer":1,"explain":"Satellites support weather forecasting, communication, and scientific research."},{"kind":"tap","prompt":"Tap the TRUE statement about the Moon.","options":["The Moon produces its own light","The Moon reflects sunlight, and its phases result from seeing different lit portions from Earth","The Moon's phases repeat every single day","The Moon never orbits the Earth"],"answer":1,"explain":"The Moon only reflects sunlight; its phases come from viewing different lit portions as it orbits Earth."},{"kind":"mcq","prompt":"Which calendar type combines cycles of both the Moon and the Sun?","options":["Purely lunar","Purely solar","Luni-solar","Neither"],"answer":2,"explain":"A luni-solar calendar adapts to both the lunar and solar cycles."},{"kind":"mcq","prompt":"About how many days does a full cycle of the Moon's phases take?","options":["7 days","About 29.5 days","365 days","1 day"],"answer":1,"explain":"A full lunar cycle takes roughly 29.5 days."},{"kind":"sort","prompt":"Sort this fact about the Moon into the correct bin.","item":"The Moon","bins":["Produces its own light","Reflects sunlight"],"answer":1,"explain":"The Moon does not produce its own light — it reflects light from the Sun, and its phases come from seeing different lit portions from Earth."}],"boss":{"name":"Keeper of the Skies","taunt":"Track the heavens correctly, or drift forever lost in orbit!"}}]},{"id":"harmonyweb","index":12,"name":"Web of Harmony","subtitle":"Habitats, ecosystems, and food webs","emoji":"🌿","theme":"Living green canopy, sunlit forest floor, interconnected threads","palette":{"from":"#84cc16","to":"#4d7c0f","accent":"#365314"},"lessons":[{"id":"hw1","title":"Habitats and Ecosystems","icon":"🏞️","kind":"lesson","story":"A pond, a desert, a forest — every habitat is a stage where living and non-living things interact in a delicate dance.","teach":[{"title":"Habitat and ecosystem","body":"A habitat is a place that provides the right conditions for an organism to live and grow. Habitats have biotic components (plants, animals, microbes) and abiotic components (air, water, soil, temperature). Together, their interactions form an ecosystem.","visual":"🐟🌳💧"},{"title":"Terrestrial and aquatic","body":"Ecosystems can be terrestrial — like forests, grasslands, and deserts — or aquatic, like ponds, lakes, seas, and oceans.","visual":"🏜️🌲🌊"}],"questions":[{"kind":"mcq","prompt":"Which of these is a biotic component of a habitat?","options":["Water","Soil","Plants","Temperature"],"answer":2,"explain":"Plants are living things, making them a biotic component."},{"kind":"mcq","prompt":"The interaction between biotic and abiotic components in an area is called a/an...","options":["Habitat","Ecosystem","Food chain","Trophic level"],"answer":1,"explain":"An ecosystem is formed by the interaction of biotic and abiotic components."},{"kind":"sort","prompt":"Sort this into the correct kind of ecosystem.","item":"Pond","bins":["Terrestrial ecosystem","Aquatic ecosystem"],"answer":1,"explain":"A pond is an aquatic ecosystem, unlike grasslands, deserts, or forests, which are terrestrial."}]},{"id":"hw2","title":"Food Chains and Relationships","icon":"🍃","kind":"lesson","story":"Grass feeds a deer. The deer feeds a tiger. When the tiger dies, decomposers return everything to the soil. Nothing in nature is wasted.","teach":[{"title":"Producers, consumers, decomposers","body":"Producers (plants) make their own food. Consumers — herbivores, carnivores, omnivores — eat plants or other animals. Decomposers (bacteria, fungi) break down dead matter and recycle nutrients. A food chain shows who eats whom; connected food chains form a food web.","visual":"🌱🦌🍄"},{"title":"Living together","body":"Organisms often share special relationships: mutualism (both benefit), commensalism (one benefits, the other is unaffected), and parasitism (one benefits while the other is harmed).","visual":"🐝🌸🦟"}],"questions":[{"kind":"match","prompt":"Match each role to its description.","pairs":[["Producer","Makes its own food, e.g. a plant"],["Consumer","Eats plants or other animals"],["Decomposer","Breaks down dead matter and recycles nutrients"]],"explain":"Producers, consumers, and decomposers each play a distinct role in an ecosystem."},{"kind":"mcq","prompt":"A relationship where both organisms benefit is called...","options":["Parasitism","Mutualism","Commensalism","Competition"],"answer":1,"explain":"Mutualism is a relationship where both organisms benefit."},{"kind":"mcq","prompt":"The position an organism occupies in a food chain is called its...","options":["Habitat","Trophic level","Ecosystem","Biome"],"answer":1,"explain":"Trophic level describes an organism's position in a food chain."}]},{"id":"hw-boss","title":"Guardian of the Web","icon":"🕸️","kind":"boss","story":"Human activities like pollution, deforestation, and habitat loss threaten ecosystems — protecting them through conservation is vital.","teach":[{"title":"Threats and protection","body":"Human activities like pollution, deforestation, habitat loss, climate change, invasive species, and overexploitation of resources threaten ecosystems. Protecting them — through efforts like national parks and sanctuaries — is vital, since healthy ecosystems give us clean air, water, food, medicine, and climate regulation.","visual":"🏭🌳🛡️"}],"questions":[{"kind":"tap","prompt":"Tap the option that is NOT listed as a threat to ecosystems in the chapter.","options":["Deforestation","Pollution","Photosynthesis","Overexploitation of resources"],"answer":2,"explain":"Photosynthesis is a natural, beneficial process — not a threat to ecosystems."},{"kind":"mcq","prompt":"What do healthy ecosystems provide to humans, according to the chapter?","options":["Nothing useful","Clean air, water, food, medicine, and climate regulation","Only scenic views","Only timber"],"answer":1,"explain":"Healthy ecosystems provide many essential benefits, from clean air to medicine."},{"kind":"mcq","prompt":"National parks and sanctuaries are examples of efforts to...","options":["Destroy habitats","Conserve and protect ecosystems","Increase pollution","Expand cities"],"answer":1,"explain":"National parks and sanctuaries help conserve ecosystems and wildlife."},{"kind":"mcq","prompt":"In a relationship where one organism benefits and the other is harmed, this is called...","options":["Mutualism","Commensalism","Parasitism","Symbiosis only"],"answer":2,"explain":"Parasitism benefits one organism while harming the other."}],"boss":{"name":"The Balance Keeper","taunt":"Disturb one thread of my web, and the whole ecosystem trembles. Do you understand the balance?"}}]},{"id":"earthhome","index":13,"name":"Our Home Planet","subtitle":"Why Earth sustains life, and what threatens it","emoji":"🌍","theme":"Blue-green marble glow, orbiting light, atmosphere haze","palette":{"from":"#60a5fa","to":"#22c55e","accent":"#0c4a6e"},"lessons":[{"id":"eh1","title":"Why Earth Is Just Right","icon":"🌎","kind":"lesson","story":"Of all the planets in the solar system, only one is known to support life. What makes Earth so special?","teach":[{"title":"The Goldilocks Zone","body":"Earth orbits the Sun at just the right distance — not too hot, not too cold — where water can exist as a liquid. This region is called the habitable zone, or 'Goldilocks zone'. Earth's nearly circular orbit also keeps temperatures fairly steady all year.","visual":"☀️🌍💧"},{"title":"Gravity, ozone, and magnetism","body":"Earth's gravity is strong enough to hold its atmosphere in place, but not so strong that it crushes life. The ozone layer blocks harmful ultraviolet rays, and Earth's magnetic field shields the planet from dangerous high-energy particles from space.","visual":"🛡️☢️🧲"}],"questions":[{"kind":"mcq","prompt":"The region around a star where a planet's temperature allows liquid water to exist is called the...","options":["Asteroid belt","Habitable (Goldilocks) zone","Ozone layer","Magnetosphere"],"answer":1,"explain":"This just-right distance from a star is called the habitable, or Goldilocks, zone."},{"kind":"mcq","prompt":"What does Earth's ozone layer protect us from?","options":["Meteor impacts","Harmful ultraviolet rays from the Sun","Earthquakes","Gravity"],"answer":1,"explain":"Ozone in the atmosphere absorbs and blocks harmful ultraviolet rays."},{"kind":"mcq","prompt":"Earth's magnetic field mainly protects the planet from...","options":["Volcanic eruptions","High-energy particles from space","Ultraviolet rays","Ocean currents"],"answer":1,"explain":"The magnetic field shields Earth from damaging high-energy particles from space."}]},{"id":"eh2","title":"Reproduction: Keeping Life Going","icon":"🌱","kind":"lesson","story":"Every living thing on Earth eventually dies — yet life itself has never stopped. The secret is reproduction.","teach":[{"title":"Two paths to new life","body":"In asexual reproduction, a single parent produces new individuals that are exact copies of itself. In sexual reproduction, two parents combine their features, allowing new variations to appear in the next generation.","visual":"🌿➡️🐣"},{"title":"The four spheres of Earth","body":"The atmosphere (air), hydrosphere (water), geosphere (solid Earth), and biosphere (life) all interact together to sustain life on our planet — each depends on the others.","visual":"💨💧🪨🌳"}],"questions":[{"kind":"mcq","prompt":"In asexual reproduction, the offspring produced are...","options":["Always different from the parent","Exact copies of the single parent","A combination of two parents","Unable to survive"],"answer":1,"explain":"Asexual reproduction produces offspring that are exact copies of the single parent."},{"kind":"mcq","prompt":"Which type of reproduction allows new variations to appear in the next generation?","options":["Asexual reproduction","Sexual reproduction","Neither","Both equally"],"answer":1,"explain":"Sexual reproduction combines features from two parents, allowing new variation."},{"kind":"match","prompt":"Match each sphere of Earth to what it consists of.","pairs":[["Atmosphere","The air surrounding Earth"],["Hydrosphere","All the water on Earth"],["Geosphere","The solid part of the Earth"],["Biosphere","All life on Earth"]],"explain":"These four interacting spheres together sustain life on Earth."},{"kind":"sort","prompt":"Sort this type of reproduction into the correct bin.","item":"Asexual reproduction","bins":["Produces exact copies (no variation)","Produces variation among offspring"],"answer":0,"explain":"Asexual reproduction involves a single parent, producing offspring that are exact copies of it."}]},{"id":"eh-boss","title":"The Triple Crisis","icon":"🌡️","kind":"boss","story":"You've journeyed from invisible microbes to the edge of space. Now prove you understand what keeps this whole planet alive.","teach":[{"title":"The triple planetary crisis","body":"Climate change, biodiversity loss, and pollution together form what scientists call the triple planetary crisis — the greatest threats facing life on Earth today. Understanding science is the first step toward protecting the delicate balance our lives depend on.","visual":"🌡️🦋🏭"}],"questions":[{"kind":"mcq","prompt":"Climate change, biodiversity loss, and pollution are together known as the...","options":["Great extinction","Triple planetary crisis","Ozone hole crisis","Ice age cycle"],"answer":1,"explain":"These three challenges together are called the triple planetary crisis."},{"kind":"mcq","prompt":"Earth's nearly circular orbit around the Sun helps keep the planet's temperature...","options":["Extremely variable through the year","Fairly steady, not too hot or cold at any time","Always freezing","Always boiling"],"answer":1,"explain":"A nearly circular orbit keeps Earth's temperature fairly steady year-round."},{"kind":"tap","prompt":"Tap the sphere of Earth that consists of all living things.","options":["Atmosphere","Hydrosphere","Geosphere","Biosphere"],"answer":3,"explain":"The biosphere is made up of all living things on Earth."},{"kind":"mcq","prompt":"What do the atmosphere, hydrosphere, geosphere, and biosphere do together?","options":["Work independently with no effect on each other","Interact together to sustain life on Earth","Only exist on other planets","Cause the triple planetary crisis alone"],"answer":1,"explain":"These four spheres interact together, and this balance sustains life on Earth."}],"boss":{"name":"The Planetary Guardian","taunt":"You've journeyed from invisible microbes to the edge of space. Now prove you understand what keeps this whole planet alive — before it's too late."}}]}];